package org.slavicmyths.verify;
import java.util.*;import net.minecraft.core.*;import net.minecraft.core.registries.Registries;import net.minecraft.server.level.*;import net.minecraft.world.level.*;import net.minecraft.world.level.chunk.LevelChunk;import net.minecraft.world.level.levelgen.structure.*;import net.minecraft.world.level.levelgen.structure.placement.*;import net.minecraft.world.level.block.entity.RandomizableContainerBlockEntity;
import static org.slavicmyths.verify.Stabilization269.*;
/** Native chunk generation only: never calls Structure.generate, feature.place, or dev create. */
final class Natural269 {
 record Target(ServerLevel level,String id,ChunkPos chunk,Set<Structure> structures){}
 static final TicketType<Long> TICKET=TicketType.create("qa269_natural",Long::compare);static final List<Target> targets=new ArrayList<>();static final List<Map<String,Object>> rows=new ArrayList<>();static final Set<ChunkPos> held=new HashSet<>();static final Map<ChunkPos,Long> pending=new HashMap<>();static final Map<String,Set<String>> seen=new HashMap<>();static List<ChunkPos> footprint;static int targetIndex,index,phase;static long begin;static StructureStart found;static Target currentTarget;
 static boolean deep(){return "natural-deep".equals(System.getProperty("slavicmyths.qa269"));}
 static final Map<String,String> predictions=new HashMap<>();
 static String targetKey(String id,ChunkPos chunk){return id+"/"+chunk.toLong();}
 static String firstChoice(List<StructureSet.StructureSelectionEntry> entries,long seed,ChunkPos chunk){var random=new net.minecraft.world.level.levelgen.WorldgenRandom(new net.minecraft.world.level.levelgen.LegacyRandomSource(0));random.setLargeFeatureSeed(seed,chunk.x,chunk.z);int draw=random.nextInt(entries.stream().mapToInt(StructureSet.StructureSelectionEntry::weight).sum());for(var entry:entries){draw-=entry.weight();if(draw<0)return entry.structure().unwrapKey().orElseThrow().location().toString();}throw new IllegalStateException("native weights");}
 static boolean enough(Target target){var observed=seen.getOrDefault(target.id,Set.of());String prediction=predictions.get(targetKey(target.id,target.chunk));return deep()&&(observed.size()>=target.structures.size()||prediction!=null&&observed.contains(prediction));}
 /** Selection bias only: coarse terrain forecast does not place blocks or prove acceptance. */
 static boolean sanctuaryTerrain(ChunkPos chunk,String predicted){
  if(!Boolean.getBoolean("slavicmyths.qa269.sanctuaryTerrainFilter")||!predicted.contains("sanctuary")&&!predicted.endsWith("abode_pure_spring"))return true;
  int low=999,high=-999;var generator=w.getChunkSource().getGenerator();var random=w.getChunkSource().randomState();
  for(int dx:new int[]{0,40,80})for(int dz:new int[]{0,40,80}){
   int x=chunk.getMinBlockX()+dx,z=chunk.getMinBlockZ()+dz;
   int floor=generator.getBaseHeight(x,z,net.minecraft.world.level.levelgen.Heightmap.Types.OCEAN_FLOOR_WG,w,random);
   int top=generator.getBaseHeight(x,z,net.minecraft.world.level.levelgen.Heightmap.Types.WORLD_SURFACE_WG,w,random);
   if(floor!=top||floor<63||floor>130)return false;low=Math.min(low,floor);high=Math.max(high,floor);if(high-low>7)return false;
  }
  return !predicted.endsWith("abode_pure_spring")||low<=73;
 }
 static void initDeep()throws Exception{
  var previous=java.nio.file.Path.of("stabilization269.json");
  if(java.nio.file.Files.exists(previous)){
   var old=com.google.gson.JsonParser.parseString(java.nio.file.Files.readString(previous)).getAsJsonObject();
   if(old.has("observed_native_structures"))for(var entry:old.getAsJsonObject("observed_native_structures").entrySet())for(var value:entry.getValue().getAsJsonArray())seen.computeIfAbsent(entry.getKey(),key->new HashSet<>()).add(value.getAsString());
   if(old.has("natural_samples"))for(var entry:old.getAsJsonArray("natural_samples")){var row=entry.getAsJsonObject();if(row.has("actual_structure"))seen.computeIfAbsent(row.get("set").getAsString(),key->new HashSet<>()).add(row.get("actual_structure").getAsString());}
  }
  var sets=w.registryAccess().registryOrThrow(Registries.STRUCTURE_SET);var scan=new ArrayList<Map<String,Object>>();
  for(var entry:sets.entrySet().stream().filter(e->e.getKey().location().getNamespace().equals("slavicmyths")).sorted(Comparator.comparing(e->e.getKey().location().toString())).toList()){
   String id=entry.getKey().location().toString();if(id.endsWith("chud_city")||id.endsWith("chud_abandoned")||id.endsWith("navya_heart"))continue;
   String only=System.getProperty("slavicmyths.qa269.naturalSets","");if(!only.isEmpty()&&Arrays.stream(only.split(",")).noneMatch(name->id.equals("slavicmyths:"+name)))continue;
   if(!(entry.getValue().placement() instanceof RandomSpreadStructurePlacement placement))continue;
   var entries=entry.getValue().structures();var structures=new HashSet<Structure>();entries.forEach(e->structures.add(e.structure().value()));var observed=seen.getOrDefault(id,Set.of());if(observed.size()>=structures.size())continue;
   int selected=0,scanned=0,excluded=0;var queued=new HashMap<String,Integer>();var biomeSource=w.getChunkSource().getGenerator().getBiomeSource();var climate=w.getChunkSource().randomState().sampler();var structureState=w.getChunkSource().getGeneratorState();int maxRing=Math.clamp(Integer.getInteger("slavicmyths.qa269.naturalRing",id.endsWith("kurgan_small")?12:4),1,32);
   for(int ring=0;ring<=maxRing;ring++)for(int gx=-ring;gx<=ring;gx++)for(int gz=-ring;gz<=ring;gz++){
    if(Math.max(Math.abs(gx),Math.abs(gz))!=ring)continue;var chunk=placement.getPotentialStructureChunk(w.getSeed(),gx*placement.spacing(),gz*placement.spacing());scanned++;
    if(!placement.isStructureChunk(structureState,chunk.x,chunk.z)){excluded++;continue;}
    String predicted=firstChoice(entries,structureState.getLevelSeed(),chunk);String variants=System.getProperty("slavicmyths.qa269.naturalVariants","");if(!variants.isEmpty()&&Arrays.stream(variants.split(",")).noneMatch(name->predicted.equals("slavicmyths:"+name)))continue;if(observed.contains(predicted)||queued.getOrDefault(predicted,0)>=Math.clamp(Integer.getInteger("slavicmyths.qa269.naturalBudget",4),1,16))continue;
    boolean possible=false;for(int y:new int[]{16,24,32}){var biome=biomeSource.getNoiseBiome(chunk.x*4+2,y,chunk.z*4+2,climate);if(entries.stream().filter(choice->variants.isEmpty()||choice.structure().unwrapKey().orElseThrow().location().toString().equals(predicted)).anyMatch(choice->choice.structure().value().biomes().contains(biome))){possible=true;break;}}
    if(!possible||!sanctuaryTerrain(chunk,predicted))continue;targets.add(new Target(w,id,chunk,structures));predictions.put(targetKey(id,chunk),predicted);queued.merge(predicted,1,Integer::sum);selected++;
   }
   scan.add(Map.of("set",id,"placement_cells_examined",scanned,"native_placement_excluded",excluded,"queued_first_choices",queued,"native_candidates_queued",selected));
  }
  out.put("sanctuary_coarse_terrain_selection_only",Boolean.getBoolean("slavicmyths.qa269.sanctuaryTerrainFilter"));out.put("natural_variant_filter",System.getProperty("slavicmyths.qa269.naturalVariants",""));out.put("natural_scan_ring",System.getProperty("slavicmyths.qa269.naturalRing","default"));out.put("natural_candidate_budget",Math.clamp(Integer.getInteger("slavicmyths.qa269.naturalBudget",4),1,16));out.put("deep_scan",scan);out.put("natural_target_count",targets.size());out.put("natural_scope","targeted native biome/placement/first-weighted-choice selection; bounded per missing first-choice variant by natural_candidate_budget, rings4 (weighted kurgans12); no frequency changes, no dev creation, selection-biased sample NOT encounter frequency");
 }
 static void init(){var sets=w.registryAccess().registryOrThrow(Registries.STRUCTURE_SET);for(var entry:sets.entrySet().stream().filter(e->e.getKey().location().getNamespace().equals("slavicmyths")).sorted(Comparator.comparing(e->e.getKey().location().toString())).toList()){if(!(entry.getValue().placement() instanceof RandomSpreadStructurePlacement placement))continue;var structures=new HashSet<Structure>();entry.getValue().structures().forEach(e->structures.add(e.structure().value()));for(var level:List.of(w,w.getServer().getLevel(Level.NETHER))){boolean possible=level.getChunkSource().getGenerator().getBiomeSource().possibleBiomes().stream().anyMatch(b->structures.stream().anyMatch(s->s.biomes().contains(b)));if(possible)targets.add(new Target(level,entry.getKey().location().toString(),placement.getPotentialStructureChunk(w.getSeed(),0,0),structures));}}out.put("natural_target_count",targets.size());out.put("natural_scope","one native placement cell(0,0) per compatible registered structure set/dimension; no player, no rare encounter frequency claim; NO_VALID_START is not an availability failure");}
 static void release(){if(currentTarget!=null)for(var chunk:held)currentTarget.level.getChunkSource().removeRegionTicket(TICKET,chunk,0,269L);held.clear();pending.clear();}
 static void constructionBounds(Map<String,Object> row,StructureStart start,ServerLevel level){int low=Integer.MAX_VALUE,high=Integer.MIN_VALUE;for(var piece:start.getPieces()){List<org.slavicmyths.chud.ChudGeometry.Fill> fills=piece instanceof org.slavicmyths.chud.AbandonedPiece a?a.blueprint():piece instanceof org.slavicmyths.chud.ChudPiece c?c.blueprint():null;if(fills!=null){for(var fill:fills)if(!fill.state().isAir()){low=Math.min(low,fill.box().minY());high=Math.max(high,fill.box().maxY());}}else{low=Math.min(low,piece.getBoundingBox().minY());high=Math.max(high,piece.getBoundingBox().maxY());}}row.put("actual_nonair_construction_height",List.of(low,high));check(low>=level.getMinBuildHeight()&&high<level.getMaxBuildHeight(),"natural actual construction fits dimension "+currentTarget.id+" "+low+".."+high);}
 static void mainReward(Map<String,Object> row,List<Map<String,Object>> containers){String id=((String)row.get("actual_structure")).replace("slavicmyths:","");String expected=switch(id){case "kurgan_small"->"rewards276/kurgan_1_main";case "kurgan_warrior"->"rewards276/kurgan_2_main";case "kurgan_great"->"rewards276/kurgan_3_main";case "bandit_camp_small"->"rewards276/camp_1_main";case "bandit_camp_medium"->"rewards276/camp_2_main";case "bandit_camp_large"->"rewards276/camp_3_main";case "sanctuary_unfading_fire"->"rewards276/overworld/fire_main";case "abode_pure_spring"->"rewards276/overworld/spring_main";case "serpent_hill"->"rewards276/overworld/fortress_main";default->null;};row.put("container_scope","all containers inside native bounding box; vanilla/other structures may overlap, null table is not a valuable reward claim");if(expected!=null){String route="slavicmyths:"+expected;long count=containers.stream().filter(c->route.equals(c.get("table"))).count();row.put("expected_main_route",route);row.put("actual_main_route_count",count);check(count==1,"whole natural structure has exactly one main route "+id+" observed="+count);}}
 static boolean ready(ChunkPos chunk){var cache=currentTarget.level.getChunkSource();if(!held.contains(chunk)){cache.addRegionTicket(TICKET,chunk,0,269L);held.add(chunk);pending.put(chunk,System.nanoTime());}if(cache.getChunkNow(chunk.x,chunk.z)!=null)return true;if(System.nanoTime()-pending.get(chunk)>180_000_000_000L)throw new IllegalStateException("native FULL chunk wait180s "+currentTarget.id+" "+chunk);return false;}
 static void locateWitness(){
  if(!Boolean.getBoolean("slavicmyths.qa269.locate"))return;
  try{
   var level=currentTarget.level;var id=level.registryAccess().registryOrThrow(Registries.STRUCTURE).getKey(found.getStructure());
   var source=level.getServer().createCommandSourceStack().withLevel(level).withPosition(net.minecraft.world.phys.Vec3.atCenterOf(found.getBoundingBox().getCenter())).withSuppressedOutput();
   int records=org.slavicmyths.worldgen.ManualStructureRecords.get(level).entries().size();
   var field=org.slavicmyths.worldgen.TemplateSiteJobs.class.getDeclaredField("JOBS");field.setAccessible(true);int jobs=((Map<?,?>)field.get(null)).size();
   int result=level.getServer().getCommands().getDispatcher().execute("locate structure "+id,source);
   check(result>0,"real command dispatcher locates loaded natural start "+id);
   check(records==org.slavicmyths.worldgen.ManualStructureRecords.get(level).entries().size()&&jobs==((Map<?,?>)field.get(null)).size()&&!org.slavicmyths.worldgen.ManualStructureJobs.active(level),"locate starts no construction job/record "+id);
  }catch(Exception error){throw new RuntimeException(error);}
 }
 static void row(boolean valid){var level=currentTarget.level;var row=new LinkedHashMap<String,Object>();row.put("set",currentTarget.id);row.put("dimension",level.dimension().location().toString());row.put("candidate_chunk",List.of(currentTarget.chunk.x,currentTarget.chunk.z));row.put("predicted_first_choice",predictions.get(targetKey(currentTarget.id,currentTarget.chunk)));row.put("elapsed_seconds",(System.nanoTime()-begin)/1e9);row.put("status",valid?"PASS_NATIVE_GENERATION_SAMPLE":"NOT_RUN_NO_VALID_START_IN_THIS_CELL");if(valid){var box=found.getBoundingBox();row.put("actual_structure",level.registryAccess().registryOrThrow(Registries.STRUCTURE).getKey(found.getStructure()).toString());row.put("bounds",List.of(box.minX(),box.minY(),box.minZ(),box.maxX(),box.maxY(),box.maxZ()));row.put("pieces",found.getPieces().size());row.put("full_footprint_chunks",footprint.size());var containers=new ArrayList<Map<String,Object>>();for(var chunk:footprint)for(var tile:level.getChunkSource().getChunkNow(chunk.x,chunk.z).getBlockEntities().values())if(box.isInside(tile.getBlockPos())&&tile instanceof RandomizableContainerBlockEntity loot){var info=new LinkedHashMap<String,Object>();info.put("position",tile.getBlockPos().toShortString());info.put("block_entity",net.minecraft.core.registries.BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(tile.getType()).toString());info.put("table",loot.getLootTable()==null?null:loot.getLootTable().location().toString());containers.add(info);}row.put("containers_unopened",containers);mainReward(row,containers);check(!found.getPieces().isEmpty(),"natural native start has pieces "+currentTarget.id);constructionBounds(row,found,level);locateWitness();}if(valid)seen.computeIfAbsent(currentTarget.id,id->new HashSet<>()).add((String)row.get("actual_structure"));rows.add(row);out.put("natural_samples",rows);System.out.println("QA269_NATURAL "+row);release();targetIndex++;currentTarget=null;}
 static void tick(){try{current="natural_chunk_generation";if(currentTarget==null){while(targetIndex<targets.size()&&enough(targets.get(targetIndex)))targetIndex++;if(targetIndex>=targets.size()){if(!deep())check(!targets.isEmpty(),"actual registered native placement targets sampled");out.put("observed_native_structures",seen);finish(null);return;}currentTarget=targets.get(targetIndex);footprint=List.of(currentTarget.chunk);index=phase=0;found=null;begin=System.nanoTime();System.out.println("QA269_NATURAL_BEGIN "+currentTarget.id+" "+currentTarget.chunk+" "+currentTarget.level.dimension().location());}
  for(int n=index;n<Math.min(index+4,footprint.size());n++)ready(footprint.get(n));if(index<footprint.size()){if(ready(footprint.get(index)))index++;return;}
  if(phase==0){LevelChunk chunk=currentTarget.level.getChunkSource().getChunkNow(currentTarget.chunk.x,currentTarget.chunk.z);found=chunk.getAllStarts().entrySet().stream().filter(e->currentTarget.structures.contains(e.getKey())&&e.getValue().isValid()).map(Map.Entry::getValue).findFirst().orElse(null);if(found==null){row(false);return;}var box=found.getBoundingBox();var list=new ArrayList<ChunkPos>();for(int x=box.minX()>>4;x<=box.maxX()>>4;x++)for(int z=box.minZ()>>4;z<=box.maxZ()>>4;z++)list.add(new ChunkPos(x,z));if(list.size()>384)throw new IllegalStateException("native sample footprint exceeds bounded QA384chunks "+currentTarget.id+" "+list.size());footprint=list;index=0;phase=1;return;}row(true);
 }catch(Throwable ex){release();out.put("natural_samples",rows);finish(ex);}}
}
